1	package indexroom
2	
3	import (
4		"crypto/hmac"
5		"crypto/rand"
6		"crypto/sha256"
7		"encoding/base64"
8		"encoding/binary"
9		"encoding/hex"
10		"encoding/json"
11		"errors"
12		"fmt"
13		"sort"
14		"strings"
15		"sync/atomic"
16	)
17	
18	// ErrInvalidArgument marks a rejected query: out-of-range heights or page
19	// size, a malformed cursor, a cursor issued by another index instance, or
20	// continuation conditions that differ from the first page. It never reports
21	// chain data problems; use errors.Is to tell it apart from ErrQueryChanged.
22	var ErrInvalidArgument = errors.New("indexroom: invalid query argument")
23	
24	// ErrQueryChanged marks a continuation whose pinned range no longer matches
25	// the first page: a block in the range was replaced (even under the same
26	// hash) or the chain was shortened below the pinned upper bound. No results
27	// are returned; the caller must restart from a first-page query.
28	var ErrQueryChanged = errors.New("indexroom: query data changed")
29	
30	const (
31		// DefaultPageSize is the page length when TxQuery.PageSize is zero.
32		DefaultPageSize = 100
33		// MaxPageSize is the largest accepted TxQuery.PageSize.
34		MaxPageSize = 1000
35	)
36	
37	// TxQuery describes a transaction lookup against the main chain.
38	type TxQuery struct {
39		// From and To bound the searched heights, both inclusive. A zero From
40		// starts at height 1. A zero To pins the chain tip seen by the first
41		// page; an explicit To above the tip is clamped to it. Explicit heights
42		// must be positive, and an explicit To must not be below From.
43		From int64
44		To   int64
45		// TxIDs restricts results to these identifiers, matched by exact string
46		// comparison; an empty slice disables the filter. Duplicates and order
47		// inside the slice are irrelevant.
48		TxIDs []string
49		// PageSize picks the page length, 1..MaxPageSize; zero means
50		// DefaultPageSize. It may change between pages of the same query.
51		PageSize int
52		// Cursor continues an earlier query; empty asks for the first page. On
53		// continuation the height range and TxIDs must equal the first page's.
54		Cursor string
55	}
56	
57	// TxHit is one transaction occurrence on the main chain. The same
58	// identifier appears once per occurrence, in different blocks or several
59	// times inside one block.
60	type TxHit struct {
61		Height    int64
62		BlockHash string
63		TxID      string
64		Position  int
65	}
66	
67	// TxPage is one page of query results together with statistics over the
68	// whole filtered range. Hits are ordered by height, then by position inside
69	// the block.
70	type TxPage struct {
71		Hits []TxHit
72		// TotalMatches counts every matching occurrence in the pinned range; it
73		// does not change between pages of the same query.
74		TotalMatches int64
75		// MatchedBlocks counts the blocks holding at least one match.
76		MatchedBlocks int64
77		// ToHeight is the upper bound pinned by the first page: the requested
78		// To clamped to the chain tip seen at that moment.
79		ToHeight int64
80		// NextCursor continues the query; empty means this is the last page.
81		NextCursor string
82	}
83	
84	// QueryTxs searches the main chain for transaction occurrences matching the
85	// query. Every call observes one complete chain state: concurrent Append or
86	// Reorg calls never leak into a page, and the returned records are copies
87	// the caller may freely mutate. The query itself never modifies the index.
88	//
89	// The first page (empty Cursor) pins the filtered range and returns a
90	// continuation cursor while more results remain. Continuations reuse the
91	// pinned range — blocks appended above it are invisible to the query — and
92	// succeed as long as every block inside the range still matches the first
93	// page; otherwise they fail with ErrQueryChanged.
94	func (index *Index) QueryTxs(query TxQuery) (TxPage, error) {
95		pageSize, err := normalizePageSize(query.PageSize)
96		if err != nil {
97			return TxPage{}, err
98		}
99		if query.Cursor != "" {
100			return index.continueQuery(query, pageSize)
101		}
102		return index.firstQuery(query, pageSize)
103	}
104	
105	func normalizePageSize(size int) (int, error) {
106		if size == 0 {
107			return DefaultPageSize, nil
108		}
109		if size < 0 || size > MaxPageSize {
110			return 0, fmt.Errorf("%w: page size must be between 1 and %d", ErrInvalidArgument, MaxPageSize)
111		}
112		return size, nil
113	}
114	
115	// normalizeRange validates the requested heights and resolves the zero From
116	// default. A zero To is left as-is; it is resolved against the chain tip
117	// while holding the lock.
118	func normalizeRange(from, to int64) (int64, int64, error) {
119		if from < 0 {
120			return 0, 0, fmt.Errorf("%w: from height must be positive", ErrInvalidArgument)
121		}
122		if to < 0 {
123			return 0, 0, fmt.Errorf("%w: to height must be positive", ErrInvalidArgument)
124		}
125		if from == 0 {
126			from = 1
127		}
128		if to != 0 && to < from {
129			return 0, 0, fmt.Errorf("%w: to height is below from height", ErrInvalidArgument)
130		}
131		return from, to, nil
132	}
133	
134	func (index *Index) firstQuery(query TxQuery, pageSize int) (TxPage, error) {
135		from, to, err := normalizeRange(query.From, query.To)
136		if err != nil {
137			return TxPage{}, err
138		}
139	
140		index.mu.Lock()
141		defer index.mu.Unlock()
142	
143		if to == 0 || to > index.Tip {
144			to = index.Tip
145		}
146		page := TxPage{Hits: []TxHit{}, ToHeight: to}
147		if from > to {
148			// Empty index or a start above the tip: a successful empty result.
149			return page, nil
150		}
151		hits, blocks := index.collectLocked(from, to, query.TxIDs)
152		return index.makePageLocked(query, from, to, hits, blocks, 0, pageSize), nil
153	}
154	
155	func (index *Index) continueQuery(query TxQuery, pageSize int) (TxPage, error) {
156		payload, err := index.decodeCursor(query.Cursor)
157		if err != nil {
158			return TxPage{}, err
159		}
160		from, _, err := normalizeRange(query.From, query.To)
161		if err != nil {
162			return TxPage{}, err
163		}
164		if from != payload.From {
165			return TxPage{}, fmt.Errorf("%w: from height differs from the first page", ErrInvalidArgument)
166		}
167		if query.To != payload.ReqTo {
168			return TxPage{}, fmt.Errorf("%w: to height differs from the first page", ErrInvalidArgument)
169		}
170		if got := hex.EncodeToString(hashTxSet(query.TxIDs)); got != payload.Set {
171			return TxPage{}, fmt.Errorf("%w: transaction filter differs from the first page", ErrInvalidArgument)
172		}
173	
174		index.mu.Lock()
175		defer index.mu.Unlock()
176	
177		if index.Tip < payload.To {
178			return TxPage{}, fmt.Errorf("%w: chain tip %d is below the pinned upper bound %d",
179				ErrQueryChanged, index.Tip, payload.To)
180		}
181		if got := hex.EncodeToString(index.fingerprintLocked(payload.From, payload.To)); got != payload.FP {
182			return TxPage{}, fmt.Errorf("%w: blocks in the pinned range differ from the first page", ErrQueryChanged)
183		}
184		hits, blocks := index.collectLocked(payload.From, payload.To, query.TxIDs)
185		if payload.Off > int64(len(hits)) {
186			return TxPage{}, fmt.Errorf("%w: cursor offset is beyond the pinned results", ErrQueryChanged)
187		}
188		return index.makePageLocked(query, payload.From, payload.To, hits, blocks, payload.Off, pageSize), nil
189	}
190	
191	// makePageLocked slices one page out of the full match list and mints the
192	// continuation cursor when matches remain. The caller must hold index.mu.
193	func (index *Index) makePageLocked(query TxQuery, from, to int64, hits []TxHit, blocks int64, offset int64, pageSize int) TxPage {
194		page := TxPage{
195			TotalMatches:  int64(len(hits)),
196			MatchedBlocks: blocks,
197			ToHeight:      to,
198		}
199		rest := hits[int(offset):]
200		end := pageSize
201		if end > len(rest) {
202			end = len(rest)
203		}
204		page.Hits = append([]TxHit{}, rest[:end]...)
205		if end < len(rest) {
206			page.NextCursor = index.encodeCursor(cursorPayload{
207				V:     1,
208				From:  from,
209				ReqTo: query.To,
210				To:    to,
211				Set:   hex.EncodeToString(hashTxSet(query.TxIDs)),
212				FP:    hex.EncodeToString(index.fingerprintLocked(from, to)),
213				Off:   offset + int64(end),
214			})
215		}
216		return page
217	}
218	
219	// collectLocked gathers every matching occurrence in [from, to], ordered by
220	// height and position, plus the number of blocks holding at least one match.
221	// The caller must hold index.mu.
222	func (index *Index) collectLocked(from, to int64, txIDs []string) (hits []TxHit, blocks int64) {
223		var filter map[string]struct{}
224		if len(txIDs) > 0 {
225			filter = make(map[string]struct{}, len(txIDs))
226			for _, id := range txIDs {
227				filter[id] = struct{}{}
228			}
229		}
230		hits = []TxHit{}
231		for height := from; height <= to; height++ {
232			block := index.Blocks[height]
233			matched := false
234			for position, tx := range block.Txs {
235				if filter != nil {
236					if _, ok := filter[tx]; !ok {
237						continue
238					}
239				}
240				hits = append(hits, TxHit{Height: height, BlockHash: block.Hash, TxID: tx, Position: position})
241				matched = true
242			}
243			if matched {
244				blocks++
245			}
246		}
247		return hits, blocks
248	}
249	
250	// fingerprintLocked hashes the exact content of every block in [from, to]:
251	// height, hash, parent, and the ordered transaction list. The caller must
252	// hold index.mu.
253	func (index *Index) fingerprintLocked(from, to int64) []byte {
254		h := sha256.New()
255		var lenBuf [8]byte
256		writeString := func(s string) {
257			binary.BigEndian.PutUint64(lenBuf[:], uint64(len(s)))
258			h.Write(lenBuf[:])
259			h.Write([]byte(s))
260		}
261		for height := from; height <= to; height++ {
262			block := index.Blocks[height]
263			binary.BigEndian.PutUint64(lenBuf[:], uint64(block.Height))
264			h.Write(lenBuf[:])
265			writeString(block.Hash)
266			writeString(block.Parent)
267			binary.BigEndian.PutUint64(lenBuf[:], uint64(len(block.Txs)))
268			h.Write(lenBuf[:])
269			for _, tx := range block.Txs {
270				writeString(tx)
271			}
272		}
273		return h.Sum(nil)
274	}
275	
276	// hashTxSet hashes the deduplicated, sorted identifier set so that cursor
277	// validation is insensitive to duplicates and ordering.
278	func hashTxSet(txIDs []string) []byte {
279		unique := make(map[string]struct{}, len(txIDs))
280		sorted := make([]string, 0, len(txIDs))
281		for _, id := range txIDs {
282			if _, ok := unique[id]; ok {
283				continue
284			}
285			unique[id] = struct{}{}
286			sorted = append(sorted, id)
287		}
288		sort.Strings(sorted)
289		h := sha256.New()
290		var lenBuf [8]byte
291		for _, id := range sorted {
292			binary.BigEndian.PutUint64(lenBuf[:], uint64(len(id)))
293			h.Write(lenBuf[:])
294			h.Write([]byte(id))
295		}
296		return h.Sum(nil)
297	}
298	
299	// cursorPayload is the signed state carried between pages of one query.
300	type cursorPayload struct {
301		V     int    `json:"v"`
302		From  int64  `json:"from"`
303		ReqTo int64  `json:"reqTo"`
304		To    int64  `json:"to"`
305		Set   string `json:"set"`
306		FP    string `json:"fp"`
307		Off   int64  `json:"off"`
308	}
309	
310	const cursorPrefix = "q1"
311	
312	// encodeCursor serializes the payload and signs it with the per-instance
313	// key, so cursors are self-contained yet unusable on any other index.
314	func (index *Index) encodeCursor(payload cursorPayload) string {
315		raw, err := json.Marshal(payload)
316		if err != nil {
317			panic(err) // cursorPayload only contains marshalable fields
318		}
319		body := base64.RawURLEncoding.EncodeToString(raw)
320		mac := hmac.New(sha256.New, index.key[:])
321		mac.Write([]byte(cursorPrefix + "." + body))
322		sig := base64.RawURLEncoding.EncodeToString(mac.Sum(nil))
323		return cursorPrefix + "." + body + "." + sig
324	}
325	
326	// decodeCursor verifies the signature before trusting any payload field;
327	// every failure is an argument error, never a data-changed error.
328	func (index *Index) decodeCursor(cursor string) (cursorPayload, error) {
329		var payload cursorPayload
330		parts := strings.Split(cursor, ".")
331		if len(parts) != 3 || parts[0] != cursorPrefix {
332			return payload, fmt.Errorf("%w: malformed cursor", ErrInvalidArgument)
333		}
334		sig, err := base64.RawURLEncoding.DecodeString(parts[2])
335		if err != nil {
336			return payload, fmt.Errorf("%w: malformed cursor", ErrInvalidArgument)
337		}
338		mac := hmac.New(sha256.New, index.key[:])
339		mac.Write([]byte(parts[0] + "." + parts[1]))
340		if !hmac.Equal(sig, mac.Sum(nil)) {
341			return payload, fmt.Errorf("%w: cursor not recognized by this index", ErrInvalidArgument)
342		}
343		raw, err := base64.RawURLEncoding.DecodeString(parts[1])
344		if err != nil {
345			return payload, fmt.Errorf("%w: malformed cursor", ErrInvalidArgument)
346		}
347		if err := json.Unmarshal(raw, &payload); err != nil || payload.V != 1 {
348			return payload, fmt.Errorf("%w: malformed cursor", ErrInvalidArgument)
349		}
350		return payload, nil
351	}
352	
353	var keyFallback atomic.Uint64
354	
355	// newKey derives the per-instance cursor signing key. crypto/rand is not
356	// expected to fail; the counter fallback still keeps keys unique per
357	// instance so cursors never validate across indexes.
358	func newKey() [32]byte {
359		var key [32]byte
360		if _, err := rand.Read(key[:]); err != nil {
361			binary.BigEndian.PutUint64(key[:8], keyFallback.Add(1))
362		}
363		return key
364	}
