24	// genericSnapshot is a schema-free view of exported bytes for invariant
25	// checks that should not depend on the production struct tags.
26	type genericSnapshot struct {
27		Version int64 `json:"version"`
28		Tip     int64 `json:"tip"`
29		Blocks  []struct {
30			Height int64    `json:"height"`
31			Hash   string   `json:"hash"`
32			Parent string   `json:"parent"`
33			Txs    []string `json:"txs"`
34		} `json:"blocks"`
