402	func (r *errReader) Read(p []byte) (int, error) {
403		if len(r.data) == 0 {
404			return 0, r.err
405		}
406		n := copy(p, r.data)
407		r.data = r.data[n:]
408		return n, nil
409	}
410	
411	func TestRestoreReadFailureLeavesIndexUntouched(t *testing.T) {
412		index := txChain(t, []string{"a"}, []string{"b"})
413		blocks, byHash, tip := snapshot(index)
414		boom := errors.New("connection reset")
415		raw := exportString(t, index)
416		err := index.Restore(&errReader{data: []byte(raw[:len(raw)/2]), err: boom})
417		if !errors.Is(err, boom) {
418			t.Fatalf("err=%v, want the read failure", err)
419		}
420		requireUnchanged(t, index, blocks, byHash, tip)
421	}
422	
423	func TestRestoreFailureKeepsCursorsAlive(t *testing.T) {
424		index := txChain(t,
425			[]string{"a"},
426			[]string{"b"},
427			[]string{"c"},
428		)
429		first, err := index.QueryTxs(TxQuery{PageSize: 1})
430		if err != nil {
431			t.Fatal(err)
432		}
433		cursor := first.NextCursor
434		if cursor == "" {
435			t.Fatal("expected a continuation cursor")
436		}
437		// The invalid block sits at the very end of the snapshot.
438		bad := `{"version":1,"tip":3,"blocks":[` +
439			`{"height":1,"hash":"x1","parent":"g","txs":[]},` +
440			`{"height":2,"hash":"x2","parent":"x1","txs":[]},` +
441			`{"height":3,"hash":"","parent":"x2","txs":[]}` +
442			`]}`
443		if err := index.Restore(strings.NewReader(bad)); !errors.Is(err, ErrInvalidSnapshot) {
444			t.Fatalf("err=%v, want ErrInvalidSnapshot", err)
445		}
446		// The cursor issued before the failed restore still pages to the end.
447		pages := collectPages(t, index, TxQuery{PageSize: 1, Cursor: cursor})
448		var all []TxHit
449		for _, page := range pages {
450			all = append(all, page.Hits...)
451		}
452		want := []TxHit{
453			{Height: 2, BlockHash: "h2", TxID: "b", Position: 0},
454			{Height: 3, BlockHash: "h3", TxID: "c", Position: 0},
455		}
456		if !reflect.DeepEqual(all, want) {
457			t.Fatalf("hits=%v, want %v", all, want)
458		}
459	}
