461	func TestRestoreSameContentKeepsCursorDifferentContentKills(t *testing.T) {
462		build := func(t *testing.T) (*Index, string) {
463			t.Helper()
464			index := txChain(t,
465				[]string{"a"},
466				[]string{"b"},
467				[]string{"c"},
468			)
469			first, err := index.QueryTxs(TxQuery{PageSize: 1})
470			if err != nil {
471				t.Fatal(err)
472			}
473			return index, first.NextCursor
474		}
475	
476		t.Run("identical restore keeps the cursor", func(t *testing.T) {
477			index, cursor := build(t)
478			raw := exportString(t, index)
479			if err := index.Restore(strings.NewReader(raw)); err != nil {
480				t.Fatal(err)
481			}
482			page, err := index.QueryTxs(TxQuery{PageSize: 1, Cursor: cursor})
