484				t.Fatalf("continuation after identical restore failed: %v", err)
485			}
486			want := []TxHit{{Height: 2, BlockHash: "h2", TxID: "b", Position: 0}}
487			if !reflect.DeepEqual(page.Hits, want) {
488				t.Fatalf("hits=%v, want %v", page.Hits, want)
489			}
490		})
491	
492		t.Run("changed range kills the cursor", func(t *testing.T) {
493			index, cursor := build(t)
494			snap := `{"version":1,"tip":3,"blocks":[` +
495				`{"height":1,"hash":"h1","parent":"genesis","txs":["a"]},` +
496				`{"height":2,"hash":"h2","parent":"h1","txs":["CHANGED"]},` +
497				`{"height":3,"hash":"h3","parent":"h2","txs":["c"]}` +
498				`]}`
499			if err := index.Restore(strings.NewReader(snap)); err != nil {
500				t.Fatal(err)
501			}
502			if _, err := index.QueryTxs(TxQuery{PageSize: 1, Cursor: cursor}); !errors.Is(err, ErrQueryChanged) {
503				t.Fatalf("err=%v, want ErrQueryChanged", err)
504			}
505		})
506	
507		t.Run("shortened chain kills the cursor", func(t *testing.T) {
508			index, cursor := build(t)
509			snap := `{"version":1,"tip":1,"blocks":[` +
510				`{"height":1,"hash":"h1","parent":"genesis","txs":["a"]}` +
511				`]}`
512			if err := index.Restore(strings.NewReader(snap)); err != nil {
513				t.Fatal(err)
514			}
515			if _, err := index.QueryTxs(TxQuery{PageSize: 1, Cursor: cursor}); !errors.Is(err, ErrQueryChanged) {
516				t.Fatalf("err=%v, want ErrQueryChanged", err)
517			}
518		})
519	}
