1	package indexroom
2	
3	import "fmt"
4	
5	// MaxTimeSegments caps the number of segments a single time-windowed
6	// aggregation may return.
7	const MaxTimeSegments = 10000
8	
9	// TimeStatsQuery describes a time-windowed transaction aggregation over the
10	// main chain. It reuses the height range and transaction filter of TxQuery
11	// but never paginates: the whole window is aggregated in one call.
12	type TimeStatsQuery struct {
13		// From and To bound the searched heights, both inclusive, with the same
14		// defaults and clamping rules as TxQuery.
15		From int64
16		To   int64
17		// TxIDs restricts results to these identifiers, matched by exact string
18		// comparison; an empty slice disables the filter. Duplicates and order
19		// inside the slice are irrelevant, and the empty identifier participates
20		// in matching like any other.
21		TxIDs []string
22		// Start and End bound the time window in Unix seconds. The window
23		// includes Start and excludes End; both must be non-negative and Start
24		// must be strictly smaller than End.
25		Start int64
26		End   int64
27		// Segment is the segment length in seconds; it must be positive. The
28		// first segment starts at Start, every later segment follows on the same
29		// grid, and the last segment is truncated at End.
30		Segment int64
31	}
32	
33	// TimeSegment is one segment of a time-windowed aggregation.
34	type TimeSegment struct {
35		// Start is the inclusive lower bound of the segment (Unix seconds).
36		Start int64
37		// End is the exclusive upper bound; the final segment is truncated at
38		// the requested window end.
39		End int64
40		// TxCount is the number of matching transaction occurrences in the
41		// segment: the same identifier counts once per occurrence, including
42		// duplicates inside one block.
43		TxCount int64
44		// UniqueTxIDs is the number of distinct matching identifiers in the
45		// segment.
46		UniqueTxIDs int64
47		// MatchedBlocks is the number of blocks in the segment holding at least
48		// one matching transaction.
49		MatchedBlocks int64
50	}
51	
52	// TimeStats is the result of a time-windowed aggregation.
53	type TimeStats struct {
54		// Segments covers the requested window in ascending time order. Every
55		// segment is present even when it holds no matching transaction.
56		Segments []TimeSegment
57		// Summary aggregates the whole window with the same口径 as one segment;
58		// its Start and End are the requested window bounds. UniqueTxIDs is
59		// deduplicated over the whole window, not summed across segments.
60		Summary TimeSegment
61		// Untimestamped counts the blocks inside the height range that carry no
62		// timestamp. Such blocks enter no segment; the count is unaffected by
63		// the transaction filter.
64		Untimestamped int64
65	}
66	
67	// QueryTimeStats aggregates transaction occurrences over a fixed time window
68	// segmented on a fixed grid. Every call observes one complete chain state:
69	// concurrent Append, Reorg, and Restore calls never mix old and new blocks,
70	// and the returned value is a copy the caller may freely mutate. The query
71	// itself never modifies the index.
72	//
73	// The window [Start, End) is split into segments of Segment seconds starting
74	// at Start; the last segment is truncated at End. All segments are returned
75	// in ascending order, including empty ones. Blocks without a timestamp are
76	// excluded from every segment and counted in Untimestamped. On empty chains,
77	// height ranges above the tip, or filters with no matches, the result still
78	// carries the requested zero-valued segments.
79	func (index *Index) QueryTimeStats(query TimeStatsQuery) (TimeStats, error) {
80		from, to, err := normalizeRange(query.From, query.To)
81		if err != nil {
82			return TimeStats{}, err
83		}
84		if query.Start < 0 {
85			return TimeStats{}, fmt.Errorf("%w: window start must be non-negative", ErrInvalidArgument)
86		}
87		if query.End < 0 {
88			return TimeStats{}, fmt.Errorf("%w: window end must be non-negative", ErrInvalidArgument)
89		}
90		if query.Start >= query.End {
91			return TimeStats{}, fmt.Errorf("%w: window start must be before end", ErrInvalidArgument)
92		}
93		if query.Segment <= 0 {
94			return TimeStats{}, fmt.Errorf("%w: segment seconds must be positive", ErrInvalidArgument)
95		}
96		// span cannot overflow: both bounds are non-negative and end > start.
97		span := query.End - query.Start
98		n := span / query.Segment
99		if span%query.Segment != 0 {
100			n++
101		}
102		if n > MaxTimeSegments {
103			return TimeStats{}, fmt.Errorf("%w: window needs %d segments, limit is %d",
104				ErrInvalidArgument, n, MaxTimeSegments)
105		}
106	
107		index.mu.Lock()
108		defer index.mu.Unlock()
109	
110		if to == 0 || to > index.Tip {
111			to = index.Tip
112		}
113		stats := TimeStats{
114			Segments: make([]TimeSegment, n),
115			Summary:  TimeSegment{Start: query.Start, End: query.End},
116		}
117		for i := range stats.Segments {
118			// (n-1)*segment <= span, so the product never overflows; the
119			// addition is checked for the truncated last segment.
120			segStart := query.Start + int64(i)*query.Segment
121			segEnd := segStart + query.Segment
122			if segEnd < segStart || segEnd > query.End {
123				segEnd = query.End
124			}
125			stats.Segments[i] = TimeSegment{Start: segStart, End: segEnd}
126		}
127		if from > to {
128			// Empty index or a start above the tip: the requested zero segments
129			// are the whole result.
130			return stats, nil
131		}
132	
133		var filter map[string]struct{}
